import os

print("CWD:", os.getcwd())
print("Files in CWD:", os.listdir('.'))

# Search for any tabular file
found = []
for root in ['/tmp', '/home', '/root', '/workspace', '/data', '/mnt', '/content', '/']:
    if os.path.isdir(root):
        for dp, dn, fn in os.walk(root):
            if dp.startswith(('/proc', '/sys', '/dev', '/usr', '/lib', '/bin', '/sbin', '/etc', '/var')):
                dn[:] = []
                continue
            for f in fn:
                if f.lower().endswith(('.csv', '.xlsx', '.xls', '.tsv')):
                    found.append(os.path.join(dp, f))
print("Tabular files found:", found if found else "None")

print("sales_data.csv exists in CWD:", os.path.exists('sales_data.csv'))
